mapper.sql:
WHERE 1 = 1
AND ( UPPER(template.template_code) LIKE CONCAT('%', UPPER(#{query}), '%') OR UPPER(template.name) LIKE CONCAT('%', UPPER(#{query}), '%') )
AND template.status = #{status}

mapper.select:
SELECT COUNT(*)
FROM policy_template
WHERE template_code = #{code}

SELECT COUNT(*)
FROM policy_version
WHERE template_id = #{templateId}

SELECT COALESCE(MAX(version_number), 0)
FROM policy_version
WHERE template_id = #{templateId}

mapper.update:
UPDATE policy_version
SET validation_json = #{validationJson},
    status = #{status},
    row_version = #{newVersion},
    updated_by = #{actorId},
    updated_at = #{now}
WHERE template_id = #{templateId}
  AND version_id = #{versionId}
  AND status IN ('DRAFT', 'VALIDATED')
  AND row_version = #{expectedVersion}

UPDATE policy_version
SET status = #{status},
    change_reason = #{changeReason},
    snapshot_json = #{snapshotJson},
    snapshot_digest = #{snapshotDigest},
    row_version = #{newVersion},
    updated_by = #{actorId},
    updated_at = #{now},
    published_at = #{publishedAt}
WHERE template_id = #{templateId}
  AND version_id = #{versionId}
  AND status = #{expectedStatus}
  AND row_version = #{expectedVersion}

UPDATE policy_version
SET status = 'DRAFT',
    validation_json = NULL,
    row_version = #{newVersion},
    updated_by = #{actorId},
    updated_at = #{now}
WHERE template_id = #{templateId}
  AND version_id = #{versionId}
  AND status IN ('DRAFT', 'VALIDATED')
  AND row_version = #{expectedVersion}

UPDATE policy_version
SET row_version = #{newVersion},
    updated_by = #{actorId},
    updated_at = #{now}
WHERE template_id = #{templateId}
  AND version_id = #{versionId}
  AND status = #{expectedStatus}
  AND row_version = #{expectedVersion}
